import AppKit

/// Polls the system pasteboard and records what gets copied.
@MainActor
final class ClipboardMonitor {
    private let store: ClipStore
    private let pasteboard = NSPasteboard.general
    private var lastChangeCount: Int
    private var timer: Timer?
    var paused = false

    /// Markers apps (mainly password managers) set to say "do not record this".
    private static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]
    private static let maxTextBytes = 1_000_000
    private static let maxImageBytes = 40_000_000

    init(store: ClipStore) {
        self.store = store
        lastChangeCount = pasteboard.changeCount
    }

    func start() {
        let timer = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.poll() }
        }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    /// Call after writing to the pasteboard ourselves so the write is not re-recorded.
    func ignoreCurrentContents() {
        lastChangeCount = pasteboard.changeCount
    }

    private func poll() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        guard !paused else { return }

        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.skipTypes) else { return }

        // Only ordinary apps count as a source; system prompts and background
        // agents can be "frontmost" for a moment without being where the copy happened.
        var front = NSWorkspace.shared.frontmostApplication
        if front?.activationPolicy != .regular { front = nil }
        let appName = front?.localizedName
        let bundleID = front?.bundleIdentifier

        // 1. Files and folders copied in Finder.
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self],
                                             options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let paths = urls.map(\.path)
            store.add(Clip(kind: .file, filePaths: paths, sourceApp: appName, sourceBundleID: bundleID,
                           hash: sha256Hex(Data(("f:" + paths.joined(separator: "\n")).utf8))))
            return
        }

        let string = pasteboard.string(forType: .string)
        let hasText = !(string ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let hasImage = types.contains(NSPasteboard.PasteboardType.png.rawValue)
            || types.contains(NSPasteboard.PasteboardType.tiff.rawValue)

        // 2. Images. Rich-text copies (documents, spreadsheets) often carry a picture
        //    of the selection too; those are treated as text.
        let richText = types.contains(NSPasteboard.PasteboardType.rtf.rawValue)
        if hasImage, !(hasText && richText), let png = pngDataFromPasteboard() {
            guard png.count <= Self.maxImageBytes else { return }
            var clip = Clip(kind: .image, sourceApp: appName, sourceBundleID: bundleID, hash: sha256Hex(png))
            if let (w, h) = pixelSize(ofImageData: png) { clip.pixelWidth = w; clip.pixelHeight = h }
            store.add(clip, imageData: png)
            return
        }

        // 3. Text and links.
        if hasText, let string, string.utf8.count <= Self.maxTextBytes {
            store.add(Clip(kind: looksLikeLink(string) ? .link : .text,
                           text: string, sourceApp: appName, sourceBundleID: bundleID,
                           hash: sha256Hex(Data(("t:" + string).utf8))))
        }
    }

    private func pngDataFromPasteboard() -> Data? {
        if let png = pasteboard.data(forType: .png) { return png }
        guard let tiff = pasteboard.data(forType: .tiff),
              let rep = NSBitmapImageRep(data: tiff) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }
}

/// Watches the macOS screenshots folder and adds new screenshots to the history.
final class ScreenshotWatcher {
    private let onScreenshot: (URL) -> Void
    private let queue = DispatchQueue(label: "clipshelf.screenshots")
    private var source: DispatchSourceFileSystemObject?
    private var seen = Set<String>()
    private let startedAt = Date()
    private static let extensions: Set<String> = ["png", "jpg", "jpeg", "heic", "tiff"]

    init(onScreenshot: @escaping (URL) -> Void) {
        self.onScreenshot = onScreenshot
    }

    /// Where macOS saves screenshots: the user's setting, or the Desktop.
    static var folder: URL {
        if let custom = UserDefaults(suiteName: "com.apple.screencapture")?.string(forKey: "location"),
           !custom.isEmpty {
            return URL(fileURLWithPath: (custom as NSString).expandingTildeInPath, isDirectory: true)
        }
        return FileManager.default.urls(for: .desktopDirectory, in: .userDomainMask)[0]
    }

    func start() {
        queue.async { [weak self] in self?.attach() }
    }

    private func attach() {
        let folder = Self.folder
        // Opening the folder is what triggers the macOS "access files in your Desktop
        // folder" prompt. If access is not there yet, try again later.
        let fd = open(folder.path, O_EVTONLY)
        guard fd >= 0, (try? FileManager.default.contentsOfDirectory(atPath: folder.path)) != nil else {
            if fd >= 0 { close(fd) }
            queue.asyncAfter(deadline: .now() + 60) { [weak self] in self?.attach() }
            return
        }
        let source = DispatchSource.makeFileSystemObjectSource(fileDescriptor: fd, eventMask: .write, queue: queue)
        source.setEventHandler { [weak self] in
            // Give macOS a moment to finish writing and renaming the file.
            self?.queue.asyncAfter(deadline: .now() + 0.7) { self?.scan(folder) }
        }
        source.setCancelHandler { close(fd) }
        source.resume()
        self.source = source
    }

    private func scan(_ folder: URL) {
        let keys: [URLResourceKey] = [.creationDateKey, .isRegularFileKey]
        guard let items = try? FileManager.default.contentsOfDirectory(
            at: folder, includingPropertiesForKeys: keys, options: [.skipsHiddenFiles]) else { return }
        for url in items where !seen.contains(url.path) {
            guard Self.extensions.contains(url.pathExtension.lowercased()),
                  let values = try? url.resourceValues(forKeys: Set(keys)),
                  values.isRegularFile == true,
                  let created = values.creationDate, created >= startedAt,
                  Self.isScreenshot(url) else { continue }
            seen.insert(url.path)
            onScreenshot(url)
        }
    }

    private static func isScreenshot(_ url: URL) -> Bool {
        if getxattr(url.path, "com.apple.metadata:kMDItemIsScreenCapture", nil, 0, 0, 0) >= 0 { return true }
        let name = url.lastPathComponent.lowercased()
        return name.hasPrefix("screenshot") || name.hasPrefix("screen shot")
    }
}
